          "analogy": "يشبه النوع unknown طرداً بريدياً مغلفاً لا تعرف ما بداخله؛ يمنعك النظام من فتحه واستخدامه حتى تفحصه بجهاز الكشف (Type Narrowing) وتتأكد من سلامته.",
          "why": "تبرز أهمية (استخدام Type Guards) في حل مشكلات الاختناق البرمجي، ضمان استقرار الخدمات الخلفية عند تزايد أحمال المستخدمين، وفصل المسؤوليات لتحقيق كود نظيف وسهل الصيانة والاختبار.",
